import React, { useState, useEffect } from 'react';
import PlayerRow from './PlayerRow';
import ChampionsLeagueFooter from './ChampionsLeagueFooter';

const ChampionsLeagueScorers = () => {
  const [players, setPlayers] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    // Simular carga de datos
    setIsLoading(true);

    // Datos de ejemplo - En una aplicación real esto vendría de una API
    const scorersData = [
      { position: 1, name: 'Cristiano Ronaldo', team: 'Real Madrid/Manchester United', goals: 140 },
      { position: 2, name: 'Lionel Messi', team: 'Barcelona/PSG', goals: 129 },
      { position: 3, name: 'Robert Lewandowski', team: 'Bayern Munich/Barcelona', goals: 91 },
      { position: 4, name: 'Karim Benzema', team: 'Real Madrid', goals: 86 },
      { position: 5, name: 'Raúl González', team: 'Real Madrid/Schalke 04', goals: 71 },
      { position: 6, name: 'Ruud van Nistelrooy', team: 'PSV/Manchester United/Real Madrid', goals: 56 },
      { position: 7, name: 'Thomas Müller', team: 'Bayern Munich', goals: 53 },
      { position: 8, name: 'Thierry Henry', team: 'Monaco/Arsenal/Barcelona', goals: 50 },
      { position: 9, name: 'Kylian Mbappé', team: 'Monaco/PSG', goals: 45 },
      { position: 10, name: 'Erling Haaland', team: 'Salzburg/Borussia Dortmund/Manchester City', goals: 41 },
    ];

    setTimeout(() => {
      setPlayers(scorersData);
      setIsLoading(false);
    }, 800); // Simular delay de red
  }, []);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-blue-500 mx-auto"></div>
          <p className="mt-4 text-lg text-gray-600">Cargando goleadores...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center text-red-500">
          <p className="text-2xl font-bold">Error al cargar los datos</p>
          <p className="mt-2">{error}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="bg-white shadow rounded-lg overflow-hidden">
          <div className="p-6 bg-blue-600 text-white">
            <h1 className="text-3xl font-bold">Máximos Goleadores de la UEFA Champions League</h1>
            <p className="mt-2 text-blue-100">Histórico de jugadores con más goles en la competición</p>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-100">
                <tr>
                  <th className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Pos</th>
                  <th className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Jugador</th>
                  <th className="py-3 px-4 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Equipos</th>
                  <th className="py-3 px-4 text-center text-xs font-medium text-gray-500 uppercase tracking-wider">Goles</th>
                </tr>
              </thead>
              <tbody>
                {players.map((player) => (
                  <PlayerRow
                    key={player.position}
                    position={player.position}
                    name={player.name}
                    team={player.team}
                    goals={player.goals}
                  />
                ))}
              </tbody>
            </table>
          </div>

          <ChampionsLeagueFooter />
        </div>
      </div>
    </div>
  );
};

export default ChampionsLeagueScorers;
